class Solution {
public:
    int countSpecialNumbers(int n) {
        std::string s = std::to_string(n);
        int L = s.size();
        int ans = 0;
        for (int k = 1; k < L; ++k) {
            int prod = 9, avail = 9;
            for (int j = 0; j < k - 1; ++j) prod *= avail--;
            ans += prod;
        }
        std::vector<bool> seen(10, false);
        bool valid = true;
        for (int i = 0; i < L; ++i) {
            int digit = s[i] - '0';
            int start = (i == 0) ? 1 : 0;
            for (int d = start; d < digit; ++d) {
                if (!seen[d]) {
                    int avail = 10 - (i + 1);
                    int prod = 1;
                    for (int j = 0; j < L - 1 - i; ++j) prod *= avail--;
                    ans += prod;
                }
            }
            if (seen[digit]) {
                valid = false;
                break;
            }
            seen[digit] = true;
        }
        if (valid) ans++;
        return ans;
    }
};

