var countSpecialNumbers = function(n) {
    const s = String(n);
    const L = s.length;
    let ans = 0;
    for (let k = 1; k < L; ++k) {
        let prod = 9, avail = 9;
        for (let j = 0; j < k - 1; ++j) {
            prod *= avail;
            avail--;
        }
        ans += prod;
    }
    const seen = new Set();
    let valid = true;
    for (let i = 0; i < L; ++i) {
        const digit = Number(s[i]);
        const start = (i === 0) ? 1 : 0;
        for (let d = start; d < digit; ++d) {
            if (!seen.has(d)) {
                let avail = 10 - (i + 1);
                let prod = 1;
                for (let j = 0; j < L - 1 - i; ++j) {
                    prod *= avail;
                    avail--;
                }
                ans += prod;
            }
        }
        if (seen.has(digit)) {
            valid = false;
            break;
        }
        seen.add(digit);
    }
    if (valid) ans++;
    return ans;
};
